<?php require 'includes/auth.php';require_login();require 'config/database.php';$pdo=db();
$fields=['database_name', 'database_engine', 'storage', 'status'];
if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM cloud_databases WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: databases.php');exit;}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM cloud_databases WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch(PDO::FETCH_ASSOC);}
if($_SERVER['REQUEST_METHOD']==='POST'){$vals=[];foreach($fields as $f)$vals[]=$_POST[$f]??'';if(!empty($_POST['id'])){$set=implode(',',array_map(fn($f)=>"$f=?", $fields));$pdo->prepare('UPDATE cloud_databases SET '+$set+' WHERE id=?')->execute(array_merge($vals,[(int)$_POST['id']]));}else{$cols=implode(',',$fields);$marks=rtrim(str_repeat('?,',count($fields)),',');$pdo->prepare('INSERT INTO cloud_databases ('+$cols+') VALUES ('+$marks+')')->execute($vals);}header('Location: databases.php');exit;}
$rows=$pdo->query('SELECT * FROM cloud_databases ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);include 'includes/header.php';include 'includes/sidebar.php';?>
<main><header class="dash-head"><div><p class="tag">MANAGEMENT</p><h1>Cloud Databases</h1></div></header>
<div class="two-col"><form class="card form" method="post"><h2><?= $edit?'Edit':'Add New' ?> Cloud Database</h2><input type="hidden" name="id" value="<?=$edit['id']??''?>"><?php foreach($fields as $f):?><label><?=ucwords(str_replace('_',' ',$f))?><input name="<?=$f?>" value="<?=htmlspecialchars($edit[$f]??'')?>" required></label><?php endforeach;?><button class="btn">Save Resource</button></form>
<div class="card table-wrap"><table><thead><tr><th>ID</th><?php foreach($fields as $f):?><th><?=ucwords(str_replace('_',' ',$f))?></th><?php endforeach;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><?php foreach($fields as $f):?><td><?=htmlspecialchars($r[$f])?></td><?php endforeach;?><td><a href="?edit=<?=$r['id']?>">Edit</a> · <a class="danger" onclick="return confirm('Delete this item?')" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div></main><?php include 'includes/footer.php'; ?>